import{_ as d,o as e,c as o,a3 as a}from"./chunks/framework.qCVWde4n.js";const b=JSON.parse('{"title":"沙盒与调试开关","description":"","frontmatter":{},"headers":[],"relativePath":"features/sandbox.md","filePath":"features/sandbox.md","lastUpdated":null}'),r={name:"features/sandbox.md"};function s(c,t,l,n,i,h){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="沙盒与调试开关" tabindex="-1">沙盒与调试开关 <a class="header-anchor" href="#沙盒与调试开关" aria-label="Permalink to &quot;沙盒与调试开关&quot;">​</a></h1><p>这一类参数会<strong>显著改变游戏体验</strong>，用途是方便调试、沙盒玩、或者快速体验内容。<strong>用之前请想清楚。</strong></p><h2 id="全部开关" tabindex="-1">全部开关 <a class="header-anchor" href="#全部开关" aria-label="Permalink to &quot;全部开关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数键</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>sandbox.timeScale</code></td><td>1.0</td><td>游戏时间缩放（0 = 暂停，1 = 原版，可快进/慢放）</td></tr><tr><td><code>sandbox.instantRepair</code></td><td>0</td><td>玩家舰船立即修好</td></tr><tr><td><code>sandbox.startRenown</code></td><td>0</td><td>新战役额外起始威望（千）</td></tr><tr><td><code>unlock.allShips</code></td><td>0</td><td>沙盒解锁全部内置舰级</td></tr><tr><td><code>local.versus</code></td><td>0</td><td>本地双人热座（关 AI）</td></tr><tr><td><code>debug.verbose</code></td><td>0</td><td>调试日志开关</td></tr></tbody></table><hr><h2 id="sandbox-timescale-——-全局时间缩放" tabindex="-1"><code>sandbox.timeScale</code> —— 全局时间缩放 <a class="header-anchor" href="#sandbox-timescale-——-全局时间缩放" aria-label="Permalink to &quot;`sandbox.timeScale` —— 全局时间缩放&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">这是全框架最需要注意的参数</p><p>它控制<strong>游戏时间的流速</strong>，会影响<strong>所有按时间推进的东西</strong>：</p><ul><li>开火动画、装填动画</li><li>舰船机动</li><li><strong>AI 的行动</strong></li><li>场景转场、界面补间</li></ul><p>所以把它调快，不只是「动画变快」—— <strong>整个游戏节奏都会变</strong>。</p></div><table tabindex="0"><thead><tr><th>值</th><th>效果</th></tr></thead><tbody><tr><td><code>0</code></td><td><strong>暂停</strong>（游戏冻结，像死机）</td></tr><tr><td><code>0.5</code></td><td>慢放</td></tr><tr><td><code>1.0</code></td><td>原版（默认）</td></tr><tr><td><code>2.0</code></td><td>快进</td></tr><tr><td><code>3.0</code></td><td>很快</td></tr></tbody></table><h3 id="最常见的困惑-「为什么点了发射就什么都没了」" tabindex="-1">最常见的困惑：「为什么点了发射就什么都没了」 <a class="header-anchor" href="#最常见的困惑-「为什么点了发射就什么都没了」" aria-label="Permalink to &quot;最常见的困惑：「为什么点了发射就什么都没了」&quot;">​</a></h3><p>如果你把倍速调到 <code>x3</code>，然后按发射：</p><p><strong>整个战斗推进会瞬间完成</strong> —— 你会看到「点了发射，然后一瞬间就进了敌方回合」，感觉像<strong>点了发射后什么都没发生</strong>。</p><div class="tip custom-block"><p class="custom-block-title">遇到这种情况怎么办</p><p><strong>点悬浮窗上的倍速按钮，把它调回 x1。</strong></p><p>悬浮窗旁边有个 <code>x1</code> 按钮，点一下循环 <code>x1 → x2 → x3 → x1</code>。倍速高于原速时按钮会有<strong>警示色</strong>，提醒你现在不是正常速度。</p></div><h3 id="为什么倍速不保存" tabindex="-1">为什么倍速不保存 <a class="header-anchor" href="#为什么倍速不保存" aria-label="Permalink to &quot;为什么倍速不保存&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">这是一个刻意的设计</p><p><code>timeScale</code> <strong>只在本次运行有效</strong>。下次启动游戏，它会<strong>强制回到 <code>1.0</code></strong>。</p><p>原因：如果它被存进设置文件，你下次打开游戏会发现「我明明什么都没调，怎么整个游戏都变快了/变慢了」，然后开始怀疑游戏坏了。</p><p>框架的选择是：<strong>宁可让你每次重新调，也不让你陷入「我不知道自己改过什么」的状态。</strong></p></div><h3 id="暂停档为什么不进快捷循环" tabindex="-1">暂停档为什么不进快捷循环 <a class="header-anchor" href="#暂停档为什么不进快捷循环" aria-label="Permalink to &quot;暂停档为什么不进快捷循环&quot;">​</a></h3><p>悬浮窗的倍速按钮循环是 <code>x1 → x2 → x3 → x1</code>，<strong>故意跳过了暂停档（0）</strong>。</p><p>原因：误触到暂停会让<strong>所有游戏协程冻结</strong>，看起来像死机，玩家第一反应是「游戏挂了」。所以不把它放在容易点到的循环里。</p><p>想用暂停，去「参数」页拖滑块。</p><hr><h2 id="sandbox-instantrepair-——-立即修理" tabindex="-1"><code>sandbox.instantRepair</code> —— 立即修理 <a class="header-anchor" href="#sandbox-instantrepair-——-立即修理" aria-label="Permalink to &quot;`sandbox.instantRepair` —— 立即修理&quot;">​</a></h2><p><code>0</code> = 关闭，<code>1</code> = 开启。</p><p>开启后，<strong>你的舰船修理时间为 0</strong>，等于随时修好，不用等。</p><div class="tip custom-block"><p class="custom-block-title">和 <code>repair.timeMul</code> 的区别</p><table tabindex="0"><thead><tr><th>参数</th><th>效果</th></tr></thead><tbody><tr><td><code>sandbox.instantRepair: 1</code></td><td>完全立即修好（开关）</td></tr><tr><td><code>repair.timeMul: 0.5</code></td><td>修理时间减半（倍率）</td></tr><tr><td><code>repair.timeMul: 0</code></td><td>也等于立即修好</td></tr></tbody></table><p>想要「稍微快点」用 <code>repair.timeMul</code>，想要「完全不要等」用 <code>instantRepair</code>。</p></div><hr><h2 id="sandbox-startrenown-——-开局威望" tabindex="-1"><code>sandbox.startRenown</code> —— 开局威望 <a class="header-anchor" href="#sandbox-startrenown-——-开局威望" aria-label="Permalink to &quot;`sandbox.startRenown` —— 开局威望&quot;">​</a></h2><p><strong>创建新战役时</strong>额外给的威望，单位<strong>千</strong>。</p><table tabindex="0"><thead><tr><th>值</th><th>效果</th></tr></thead><tbody><tr><td><code>0</code></td><td>关闭</td></tr><tr><td><code>50</code></td><td>多 5 万</td></tr><tr><td><code>100</code></td><td>多 10 万</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">只对新战役生效</p><p>已有存档不会因此变化。要给现有存档加威望，用 <a href="/AtlanticFleetSite/docs/use/save-page">存档页</a>。</p></div><hr><h2 id="unlock-allships-——-解锁全部舰级" tabindex="-1"><code>unlock.allShips</code> —— 解锁全部舰级 <a class="header-anchor" href="#unlock-allships-——-解锁全部舰级" aria-label="Permalink to &quot;`unlock.allShips` —— 解锁全部舰级&quot;">​</a></h2><p><code>0</code> = 关闭，<code>1</code> = 开启。</p><p>开启后，<strong>所有内置舰级都可用</strong>，不需要通过正常流程解锁。</p><div class="tip custom-block"><p class="custom-block-title">适合「想直接体验所有船」</p><p>如果你只是想看看所有舰船长什么样、性能如何，开这个最省事。</p><p>但要注意：<strong>这会跳过游戏的解锁进度</strong>，如果你还在意「自己一点点解锁」的成就感，就别开。</p></div><hr><h2 id="local-versus-——-本地双人热座" tabindex="-1"><code>local.versus</code> —— 本地双人热座 <a class="header-anchor" href="#local-versus-——-本地双人热座" aria-label="Permalink to &quot;`local.versus` —— 本地双人热座&quot;">​</a></h2><p><code>0</code> = 关闭，<code>1</code> = 开启。</p><p>开启后，<strong>关闭 AI，两个人在同一台手机上轮流操作</strong>。</p><div class="tip custom-block"><p class="custom-block-title">「热座」（Hot Seat）是什么意思</p><p>传统说法，指两个人共用同一台设备，一个玩完换另一个。因为设备会「热」，所以叫热座。</p><p>适合和朋友面对面轮流玩。</p></div><hr><h2 id="debug-verbose-——-调试日志" tabindex="-1"><code>debug.verbose</code> —— 调试日志 <a class="header-anchor" href="#debug-verbose-——-调试日志" aria-label="Permalink to &quot;`debug.verbose` —— 调试日志&quot;">​</a></h2><p><code>0</code> = 关闭，<code>1</code> = 开启。</p><p>开启后，框架会写<strong>更详细的日志</strong>（每一步加载、每一次参数读取）。</p><div class="warning custom-block"><p class="custom-block-title">只在排查问题时开</p><p>调试日志量很大，会让 <code>AFMOD_log.txt</code> 迅速变大（虽然有 200 KB 上限自动截断）。</p><p>出问题时让作者让你开，平时关着就行。</p></div><hr><h2 id="一张表-什么时候用哪个" tabindex="-1">一张表：什么时候用哪个 <a class="header-anchor" href="#一张表-什么时候用哪个" aria-label="Permalink to &quot;一张表：什么时候用哪个&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我想</th><th>开哪个</th></tr></thead><tbody><tr><td>快速过一遍战斗动画</td><td><code>sandbox.timeScale</code> = 2 或 3</td></tr><tr><td>仔细看每一步</td><td><code>sandbox.timeScale</code> = 0.5</td></tr><tr><td>修船不想等</td><td><code>sandbox.instantRepair</code> = 1</td></tr><tr><td>开局就有一大笔钱</td><td><code>sandbox.startRenown</code> = 100</td></tr><tr><td>想玩所有船</td><td><code>unlock.allShips</code> = 1</td></tr><tr><td>和朋友轮流玩</td><td><code>local.versus</code> = 1</td></tr><tr><td>帮人排查问题</td><td><code>debug.verbose</code> = 1</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>完整参数表 → <a href="/AtlanticFleetSite/docs/features/matrix">功能接入总表</a></li><li>倍速的详细说明 → <a href="/AtlanticFleetSite/docs/use/timescale">倍速与时间缩放</a></li><li>改存档威望 → <a href="/AtlanticFleetSite/docs/use/save-page">存档页：改威望与回合</a></li></ul>',48)])])}const u=d(r,[["render",s]]);export{b as __pageData,u as default};
